package com.zhibrary.user;
import jakarta.persistence.*;
@Entity @Table(name="users", uniqueConstraints={@UniqueConstraint(name="uk_user_email",columnNames="email"),@UniqueConstraint(name="uk_user_username",columnNames="username")}) public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String firstName; private String middleName; @Column(nullable=false) private String lastName; @Column(nullable=false) private String email; @Column(nullable=false) private String username; @Column(nullable=false) private String password; @Enumerated(EnumType.STRING) @Column(nullable=false) private UserRole role=UserRole.USER; @Column(nullable=false) private double outstandingFine; protected User(){} public User(String firstName,String middleName,String lastName,String email,String username,String password,UserRole role){this.firstName=firstName;this.middleName=middleName;this.lastName=lastName;this.email=email;this.username=username;this.password=password;this.role=role;} public Long getId(){return id;} public String getFirstName(){return firstName;} public String getMiddleName(){return middleName;} public String getLastName(){return lastName;} public String getEmail(){return email;} public String getUsername(){return username;} public String getPassword(){return password;} public UserRole getRole(){return role;} public double getOutstandingFine(){return outstandingFine;} public void addFine(double amount){outstandingFine+=amount;} }
